import{z as d,x as p,o,c as B,q as i,j as s,D as e,d as t,s as n,S as E,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Hoare 逻辑","description":"","frontmatter":{"title":"Hoare 逻辑","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hoare-logic.md","filePath":"cs/hoare-logic.md","lastUpdated":1791063341000}'),A={name:"cs/hoare-logic.md"};function h(m,a,c,u,D,f){const l=p("Mermaid");return o(),B("div",null,[a[2]||(a[2]=i('<h1 id="hoare-逻辑" tabindex="-1">Hoare 逻辑 <a class="header-anchor" href="#hoare-逻辑" aria-label="Permalink to &quot;Hoare 逻辑&quot;">​</a></h1><div class="epigraph"><p>三元组 $\\{P\\}S\\{Q\\}$：若前置 $P$ 成立则 $S$ 终止后 $Q$ 成立。赋值、顺序、条件、循环用公理与不变式，把程序正确性写成证明。</p><footer>—— 据 Hoare, An Axiomatic Basis for Computer Programming, 1969；Winskel 整理</footer></div><p>上一课<a href="/cs/natural-deduction">自然演绎</a> 证的是逻辑公式。缺口是<strong>程序</strong>：状态上的断言。<a href="/cs/to-systems-boundary">操作系统</a> 主干已封口，本课不重做语义实现，只把 Floyd–Hoare 规则钉在补层。部分正确 vs 完全正确（终止）要分开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态把变量映到值。\\(P,Q\\) 是一阶断言（可含量词）。赋值公理：\\(\\{Q[e/x]\\}x:=e\\{Q\\}\\)。顺序：把中断言接上。if：两分支后条件相同。while：不变式 \\(I\\)，体保持 \\(I\\)，退出加 \\(\\neg b\\)。部分正确：不谈循环是否停。完全正确加变式（良基下降）。</p><p>可靠：可证三元组在操作语义下为真。相对完备（Cook）：若断言语言够表达最弱前置，则真三元组可证。下一课 WP。</p><h3 id="不是测试" tabindex="-1">不是测试 <a class="header-anchor" href="#不是测试" aria-label="Permalink to &quot;不是测试&quot;">​</a></h3><p>测试给有限输入。Hoare 要不变式覆盖无穷状态。找不到不变式不是逻辑失败，是证明义务未完成。</p><p><span class="marginnote">Hoare 1969；Floyd 1967 流程图断言。Winskel 有结构化规则。本课 while 语言足够；堆与分离逻辑点名不写。</span></p><p><span class="marginnote">直觉类比：三元组像一份施工合同——前置是进场条件，程序是施工过程，后置是验收标准。赋值公理「倒着代」就是从验收反推进场：想让 \\(\\{x \\gt 0\\}\\) 在赋值后成立，进门前就得有 \\(\\{x+1 \\gt 0\\}\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对一小段求绝对值或阶乘，写不变式与变式。强调：赋值公理「倒着代」是最常见错向。并发、别名使简单 Hoare 破——本课顺序无别名。</p>',12)),(o(),s(E,null,{default:e(()=>[n(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRE%5B%22%7BP%7D%22%5D%20--%3E%20STMT%5B%22%E8%AF%AD%E5%8F%A5%20S%22%5D%0A%20%20STMT%20--%3E%20POST%5B%22%7BQ%7D%22%5D%0A%20%20STMT%20--%3E%20INV%5B%22%E5%BE%AA%E7%8E%AF%E4%B8%8D%E5%8F%98%E5%BC%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"编译器不自动给出 \\(I\\)。模型检验对有限状态可免写 \\(I\\)，后课。本课把「正确」从测试换成证明规则，与 SAT 求解的关系是：验证条件（VC）可变成公式交给求解器。",-1)),a[5]||(a[5]=r("p",null,"while 规则实际怎么用，走一圈：",-1)),(o(),s(E,null,{default:e(()=>[n(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E8%BF%9B%E5%BE%AA%E7%8E%AF%E5%89%8D%3A%20%E5%85%88%E5%BB%BA%E7%AB%8B%E4%B8%8D%E5%8F%98%E5%BC%8F%20I%22%5D%20--%3E%20B%7B%22%E5%BE%AA%E7%8E%AF%E6%9D%A1%E4%BB%B6%20b%20%E6%88%90%E7%AB%8B%3F%22%7D%0A%20%20B%20--%20%22%E6%88%90%E7%AB%8B%22%20--%3E%20H%5B%22%E4%BD%93%E7%9A%84%E5%89%8D%E5%90%8E%E9%83%BD%E6%98%AF%E4%B8%8D%E5%8F%98%E5%BC%8F%20I%22%5D%0A%20%20H%20--%3E%20B%0A%20%20B%20--%20%22%E4%B8%8D%E6%88%90%E7%AB%8B%22%20--%3E%20X%5B%22%E9%80%80%E5%87%BA%E6%97%B6%E6%9C%89%3A%20I%20%E4%B8%94%20%E9%9D%9E%20b%22%5D%0A%20%20X%20--%3E%20Q%5B%22%E7%94%B1%20I%20%E5%8A%A0%20%E9%9D%9E%20b%20%E6%8E%A8%E5%87%BA%E5%90%8E%E7%BD%AE%20Q%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">数字实例：证 <code>while n \\gt 0</code> 的递减循环终止，取变式为 \\(n\\) 本身——每转一圈体里 \\(n\\) 减 1，变式严格下降又以 0 为下界（自然数的良基序），所以不可能永远转下去；这一步补的正是「完全正确」里的终止义务。</span></p><p>终止：完全正确需要额外证明；部分正确允许死循环。</p><p>并发：Owicki–Gries 要干涉自由；分离逻辑用 \\(*\\) 谈堆不相交，本课顺序无别名。相对完备依赖断言语言能写 \\(\\mathrm{wp}\\)：一阶算术够用整数程序，不够用任意可计算断言。测试给出反例三元组；证明给出全称。完全正确把终止当证明义务，不是运行到停。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写分离逻辑，不引入依赖类型程序。不证相对完备。后课默认：\\(\\{P\\}S\\{Q\\}\\) 部分正确用不变式。下一课把 \\(P\\) 算出来：最弱前置。</p><p>部分正确允许不终止；完全正确另证变式。赋值公理倒着代是方向。不变式要人给，模型检验在有限状态上可免写。别名与堆超出本课简单语言。</p><p><span class="marginnote">常见误区：以为「测试全过 = 程序正确」。测试只覆盖试过的有限输入，Hoare 三元组是对无穷多个状态的全称断言；找不到合适的不变式只说明证明义务未完成，并不说明程序有错。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Hoare 三元组：前置、程序、后置；赋值倒着代。</li><li>while 靠不变式；终止靠变式，另证。</li><li>可靠相对操作语义；完备要断言够表达。</li><li>出处：Hoare, 1969；Floyd, 1967。</li></ul>',9))])}const P=d(A,[["render",h]]);export{_ as __pageData,P as default};
